) AS (
  VALUES 
    (450::BIGINT, 'Jary es muy buen profesor, tiene muy buen material y es una excelente persona, pero es muy relax, entonces si usted de verdad no se lo propone ni le pregunta, posiblemente no aprenda mucho en el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'c4ec93a2418ab13b8d0ed6441e4ce6e8b00bc1cd0faccb1a1a44f74b18913d35'::TEXT, ARRAY[1754]::BIGINT[]),
    (450::BIGINT, 'El profe sabe mucho, pero es muy relax y si uno no se propone preguntarle, y estar encima del curso no se aprende. Es excelente persona'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '537789ce75427c64353f278fabff6156d5884ae69eb4ad378dc49736d093c7b0'::TEXT, ARRAY[1754]::BIGINT[]),
    (450::BIGINT, 'Si quiere pasar sin ni siquiera ir a clases, Jary es el indicado, pero no va aprender absolutamente nada, no porque el profe no sepa (porque si sabe bastante), pero si usted es desinteresado él también lo va ha ser. Quizes y exámenes se hacen en forms, las tareas son un regalo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '41641c8e3fc1091ff1b334ce55d22139badc5f7997c00d18e71dfadce6c720e5'::TEXT, ARRAY[1760]::BIGINT[]),
    (450::BIGINT, 'El profesor es muy buena persona y se nota que es una persona con conocimiento amplio sobre diversos temas de la carrera. Sin embargo, las clases además de ser cortas y virtuales en su mayoría, el aprendizaje llega a ser de poco a nulo. Se pasa fácil con él pero el aprendizaje es poco o nulo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, '6eb043361eadf86a3028e0db217bd5fb6436121d457cd379149f2ec4fe76a194'::TEXT, ARRAY[1754]::BIGINT[]),
    (450::BIGINT, 'Una teja, se pasa relajado, no exigue y ademas ayuda un monton en lo que se le pregunte, no necesariamente del curso. Si quiere aprender hay que ir a clases y poner atencion, se puede aprender mucho con el, pero sin presion de pruebas. Ademas se aprende power bi'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '1afa17faf99576bc1df6e10961c6c851e9572dea797f7a1d2db8834e64f56f2f'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Si quiere pasar la materia lleve con él pero si quiere aprender no lo recomiendo mucho. Si es su única opción en serio éntrele sin mieo, preste atención en clases para aprender, pero aunque falte sepa que va a pasar, todas las evalaciones son virtuales y los trabajos grupales se hacen fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'd11db2f56071ffc0b3fc16446a0da687210338cf1786b3d4fb10f9ec9f3e5e26'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Los cursos con él se pasan fácil, pero puede ser frustrante ya que el profesor no enseña bien, no se aprende nada y hay que "batear" mucho para ver que es lo que pide en las evaluaciones'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '74ed9127c9c66720d582b71685a276d3f826b2c7aa5d9575668edc37597f0fd5'::TEXT, ARRAY[1760]::BIGINT[]),
    (450::BIGINT, 'Es un profesor que sabe muchísimo, revisando los materiales y practicando se aprende un montón! Con él aprendí muchas cosas de las que realemente hacemos como ingenieros en produ ya que siempre muestra ejemplos reales. Las clases son cortas, los quices son duros pero ayuda si uno le pone bonito.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd2b3bbb063a4947a8fee48a78f2dafa07f98be51e1a1718c6d1c1554761bd039'::TEXT, ARRAY[1745, 1754]::BIGINT[]),
    (450::BIGINT, 'Es pura vida, sabe mucho y lo transmite. Evaluaciones duras pero es facil de pasar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'b231f040ad0ce0b4bb825a2be2c64dba218559530144d30022c16b8c9febe572'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'No cumple horario y no da la materia ni ejemplos, una clase de 4 horas sólo da una y se va. Todos los semestres es lo mismo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-13T00:00:00+00:00'::TIMESTAMPTZ, '0cd92e7a95ae012befd065c8e28f401e8de1cfc4610fefa0104b075ab9096a18'::TEXT, ARRAY[1760]::BIGINT[]),
    (450::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '26bbb109fd80a53deaa228f86da019eaf92a2e1c5fc76d5327c3e3bbbd0b44d7'::TEXT, ARRAY[1760]::BIGINT[]),
    (450::BIGINT, '(Virtual) Se aprende mucho de la carrera pero no tanto del curso. El tiene mucha experiencia en calle entonces brinda ejemplos reales. Los trabajos son en grupo y hace muchos quices individuales. Ayuda un montón a atender dudas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '53124c2a1e910b6dca4aa565f1f83d76320bfb9d1f2a01dba7f942ed29dc9aa3'::TEXT, ARRAY[1776]::BIGINT[]),
    (450::BIGINT, 'Ralito ralito, exige bastante pero él no sabe explicarse, conoce mucho de todo pero no se aprende debido a que no sabe explicar con claridad, buen profesional quizás sí, pero muy mal pedagogo!!'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-03-13T00:00:00+00:00'::TIMESTAMPTZ, '954728b8f0e25a770e5fc68fef400cc16284d78bcbdadfdebcda8031269324d4'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Es muy fácil, pero la verdad es que uno no aprende mucho del curso. Aprende más uno de negocios de bebidas y de cosillas que él aprendió en la calle.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ad8d752119404c58819420eea9b28b883dcb28b676c3a25ddab32ecb89d2d477'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Lleve Logistica hace unos semestres y fue excelente. En mi proyecto de Graduación lo aprendido me sirvió mucho. Veo los comentarios que no es bueno, pero no los comparto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-13T00:00:00+00:00'::TIMESTAMPTZ, '16ea2df212479631ca2baf90255b027d3aebaa4e42c8c481051a7381ed43d032'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Se pasa facil pero no se aprende.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'dabcc042d704974e2f92c59c70d696852764e1f5a02fca9356d17c3d81ce9b95'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Sabe mucho pero no es un buen profesor, no se sabe explicar. Muy confuso y deja trabajos para nada acordes a lo que ve en clase. Quiere abarcar tanto que al final no dice nada. De fijo se pasa, pero no se aprende nada.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'c92b23de04616dfc7a95605e1e92a45beb19651ee7fd8bc2f5328e1aeb6b4f3b'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Es un buen curso. Se ven temas relevantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '10e1699b139a41cd3f579dd4adfa6024e2c56176084328c42e4042e8d9db5117'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Demasiado confuso, el curso no vale la pena y quita tiempo. La clase no sirve de nada.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-11-19T00:00:00+00:00'::TIMESTAMPTZ, '950e692c70cff678c5a7a2918a58d51d1dbc4bb377e97dfaec02b539ef9a7c86'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Muy buen profesor. Se revisan temas que son necesarios. Full recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'db58fd26d295b70b2a78d3f32ba32c76ac29472558ea9604a3db42324a832f55'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Nadie niega que tiene demasiada experiencia, pero simplemente no lo sabe transmitir. De fijo se pasa, pero sin aprender nada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'c6e940292c92a4abefb8079c88a5a8ccd953e340ee9139cd807412f64f85e655'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Mucha experiencia, ni siquiera sabe que se debe ver en el curso, el más confuso y el peor inglés de la escuela'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2018-11-07T00:00:00+00:00'::TIMESTAMPTZ, '7b825eefba427480f92304b8bbd264edff9d0b65e8da099e950ab9b003423959'::TEXT, ARRAY[3254]::BIGINT[]),
    (450::BIGINT, 'Crack'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6bc62e319cfc11bec7132abb365ded9203ed2a74f16ae8bccb0b05100b7ccb74'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Es un profe muy actualizado nada que ver con los demás de la escuela, siempre está atento en las dudas que surgan y se aprende de todo un poco.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'f49d0710ed6b4cb40264a55e4fa953510b94af2588bc1c76deaef178bea13cb7'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Clase muy rara, aprendi de temas que pense no tenian nada que ver con la carrera. Muy actualizado, me gusto lo relacionado con Machine Learning'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'cea3f2ea2f42e3316efb78ac357f93b8375bffe38037ec059fc469790632892c'::TEXT, ARRAY[1788]::BIGINT[]),
    (450::BIGINT, 'Simplemente exc profesor, 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '29ab9d65db474bc55b310c49a2530d3d141be13a552d2b246ee9ae138bf87341'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'De lo mejor en la escuela ! Un crack'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3df823d9efc1e1de78ad58a1dd82b50c555328eb736308da45fd205177ee420b'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Es un buen profesor, quizas es uno de los de mayor experiencia y se mantiene muy actualizado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, '9d788ad825ff96dedfaad51c187dfceac384c1239bc2cd1a1c42ede7d6620aa9'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Sus clases son buenas, posee mucha experiencia y da muchos tips de como es el trabajo luego de graduado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2016-11-05T00:00:00+00:00'::TIMESTAMPTZ, '8ceedbecdc5d32620722a6d60b9bf7b4b83f45a2b6e17790e849d9d42286ae9b'::TEXT, ARRAY[1745]::BIGINT[]),
    (450::BIGINT, 'Tiene mucha experiencia practica, lo cual hace sus clases muy enriquecedoras, aportando ejemplos significativos. Favorece la participacion, permitiendo la cros-fertilizacion del conocimiento. Sus clases son muy amenas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-08-06T00:00:00+00:00'::TIMESTAMPTZ, '8305f313b7fd007f3fc3a07a30992e82187757f356769a31a61a4f33e5cb3d16'::TEXT, ARRAY[1749]::BIGINT[]),
    (450::BIGINT, 'Buen profesor... Califica justo y es una persona muy accesible.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3759c01d6973c2bf0e7158fb199ba95d689ec3b84b60a4d872ac0606056a9c08'::TEXT, ARRAY[1745]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
